const s=input.state;
const e=input.event;
const a=e.type==='action'?e.actionId:'';
const stars=[1,4,7];
const buildUi=(st)=>({type:'column',children:[{type:'metric',text:'Очки',bind:'score',style:{emphasis:'number'}},{type:'text',text:'Соберите три звезды на поле.',bind:'winMessage'},{type:'grid',columns:3,minCellWidth:48,children:st.open.map((o,i)=>({type:'button',text:o?(stars.includes(i)?(i+1)+' ★':(i+1)+' ·'):String(i+1),action:'cell'+(i+1),enabledBind:'active'}))},{type:'button',text:'Заново',action:'reset'}]});
if(e.type==='preview'||e.type==='render')return {state:s,ui:buildUi(s)};
if(a==='reset'){s.score=0;s.open=[false,false,false,false,false,false,false,false,false];s.winMessage='Соберите три звезды на поле.';s.active=true;return {state:s,ui:buildUi(s)};}
if(!s.active)return {state:s};
if(/^cell[1-9]$/.test(a)){const i=Number(a.slice(4))-1;if(s.open[i])return {state:s};const next=s.open.slice();next[i]=true;s.open=next;if(stars.includes(i))s.score=s.score+1;if(s.score>=3){s.active=false;s.winMessage='Победа! Все три звезды собраны.';}else{s.winMessage='Звёзд найдено: '+s.score+' из 3.';}return {state:s,ui:buildUi(s)};}
return {state:s};
